package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in list order: newest first, a moved claim as the newest when it moved. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** The next place in the claims' list, after every claim added or moved so far. */
    @Query(value = "select next value for claim_listed_seq", nativeQuery = true)
    long nextListed();

    /** The next place in the order claims were added, after every claim added so far. */
    @Query(value = "select next value for claim_added_seq", nativeQuery = true)
    long nextAdded();

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    /**
     * The last place given in a period's numbering on the sheet (empty name: in no period), counting those
     * given up by claims re-dated out of it; 0 if none.
     */
    @Query(value = "select coalesce(max(s), 0) from (select number_seq s from claim where sheet_id = :sheetId"
            + " and number_period = :period union all select number_seq s from claim_number_retired"
            + " where sheet_id = :sheetId and number_period = :period) n", nativeQuery = true)
    int lastNumberWithin(String sheetId, String period);

    /** Give up a place in a period's numbering on the sheet, so it is never given again. */
    @Modifying
    @Query(value = "insert into claim_number_retired (sheet_id, number_period, number_seq)"
            + " values (:sheetId, :period, :seq)", nativeQuery = true)
    void retireNumberWithin(String sheetId, String period, int seq);

    /** Release every claim editor's lock on the sheet. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query(value = "update claim set locked_by = null where sheet_id = :sheetId and locked_by is not null",
            nativeQuery = true)
    void unlockAll(String sheetId);

    /** The claim on the sheet carrying the reference of this key, if any. */
    Optional<Claim> findBySheetIdAndRefKey(String sheetId, String refKey);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a DRAFT,
 * OPEN or PENDING claim can be voided (VOID). A clerk's settling above the clerk limit makes it
 * PENDING instead, until a steward approves it (SETTLED) or rejects it (OPEN again). A steward
 * may void a SETTLED claim shortly after its settlement ({@link ClaimService}); VOID is final.
 * A DRAFT claim can be deleted (DELETED): it counts nowhere and cannot change, except to be restored
 * to DRAFT on the same sheet's today it was deleted. Opening a claim whose due is above the review
 * threshold makes it REVIEW instead: it counts nowhere and has no number until a steward's review
 * opens it (OPEN); it can be voided, but not edited, settled or split.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /**
     * Whether a claim in this status may move to {@code next} by opening, settling, voiding or deleting
     * it; a PENDING claim leaves for SETTLED or OPEN only by a steward's approval or rejection, and a
     * DELETED one for DRAFT only by its restore, and a REVIEW one for OPEN only by a steward's review.
     */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING, SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT, REVIEW -> false;
        };
    }

    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like it. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward what is claimed and due. */
    public boolean counts() {
        return isOpen() || this == SETTLED;
    }
}
